import json


def load_users(path):
    with open(path) as handle:
        records = json.load(handle)
    users = []
    for record in records:
        name = record.get("name", "")
        email = record.get("email", "")
        age = record.get("age", 0)
        if not name:
            continue
        if not email:
            continue
        if age < 0:
            continue
        users.append({"name": name, "email": email, "age": age})
    return users


